export type CustomEndpoint = {
	label: string,
	base_url: string,
};

/**  A server the user described by hand, or pasted from another client's configuration (03 §8). */
export type CustomServer = {
	name: string,
	config: ConnectorConfig,
};

/**  What Settings → Data & privacy shows and what its buttons do. */
export type DataInfo = {
	data_dir: string,
	database_path: string,
	/**  Size of the database file and its WAL, in bytes. */
	database_bytes: number,
	chat_count: number,
};

/**  Who or what allowed or refused a call (04 §11). */
export type DecisionSource = "mode" | "grant" | "user_once" | "user_chat_grant" | "judge" | "guardrail" | "scope" | "plan_mode";

export type Density = "comfortable" | "compact";

/**
 *  A sign-in needs the user to type a code on the server's own page (RFC 8628, 03 §7). Sent
 *  before the browser opens, and answered by the user, not by the app.
 */
export type DeviceCodeNeeded = {
	instance_id: InstanceId,
	connector: string,
	user_code: string,
	verification_uri: string,
};

/**
 *  What the frontend receives when a command fails. Never carries secrets or paths the
 *  user did not choose. Rendered by the UI as an inline error row.
 */
export type ErrorDto = { kind: "internal"; message: string } | { kind: "invalid_input"; message: string } | { kind: "not_found"; message: string } | { kind: "io"; message: string } | { kind: "provider"; provider_kind: ProviderErrorKind; message: string } | { kind: "secrets"; message: string } | { kind: "store"; message: string };

export type ExportFormat = "markdown" | "json";

/**  The user's verdict on an assistant reply. */
export type Feedback = "good" | "bad";

/**  A standing permission for one chat (04 §8). */
export type GrantId = string;

/**  The scopes a permission card can offer, in the order they are shown (04 §7, §8). */
export type GrantScope = 
/**  This tool, from this connector, for the rest of this chat. */
"tool" | 
/**  Every read from this connector for the rest of this chat. */
"all_reads";

/**  Where a grant came from (04 §8). */
export type GrantSource = 
/**  The user chose a scope on a permission card. */
"user_prompt" | 
/**  The user answered a mid-conversation access request (04 §9). */
"access_request" | 
/**  Inherited from the project the chat belongs to. */
"project_default";

/**  An installed, configured connector. */
export type InstanceId = string;

export type Interaction = {
	id: InteractionId,
	chat_id: ChatId,
	turn_id: TurnId,
	kind: InteractionKind,
	payload: InteractionPayload,
	status: InteractionStatus,
	resolution: InteractionResolution | null,
	created_at: number,
	resolved_at: number | null,
};

/**  A decision the turn waits on: a permission prompt, an access request, a proposal. */
export type InteractionId = string;

export type InteractionKind = "permission" | "access_request" | "connector_suggestion" | "elicitation" | "auth_required" | "skill_proposal" | "memory_proposal";

/**  The kind-specific body of an interaction. */
export type InteractionPayload = { kind: "permission"; request: PermissionRequest };

/**  How an interaction ended. */
export type InteractionResolution = { kind: "permission"; decision: PermissionDecision; 
/**  Shown to the model with a denial. */
message: string | null } | 
/**  The turn was cancelled or the app restarted while the card waited. */
{ kind: "cancelled" };

export type InteractionStatus = "pending" | "resolved" | "cancelled" | "expired";

/**  A chat's count of decisions waiting for the user changed (04 §10: sidebar badges). */
export type InteractionsChanged = {
	chat_id: ChatId,
	pending: number,
};

/**  What a key check returns (OpenRouter's `GET /key`; other providers report less). */
export type KeyInfo = {
	label: string | null,
	limit_usd: number | null,
	limit_remaining_usd: number | null,
	usage_usd: number | null,
	is_free_tier: boolean | null,
};

/**  What the UI may know about a key (docs/plan/11 §4). */
export type KeyStatus = {
	present: boolean,
	/**  The last four characters, when present. */
	hint: string | null,
	/**  The last test failed with an authentication error. */
	invalid: boolean,
};

/**  Where the bytes of an image or document live. */
export type MediaSource = 
/**  Inline, base64-encoded. */
{ kind: "base64"; data: string } | 
/**  A content-addressed blob in the store. */
{ kind: "blob"; hash: string };

/**  One message in a transcript. */
export type Message = Message_Serialize | Message_Deserialize;

/**  One message in a transcript. */
export type MessageId = string;

/**  One message in a transcript. */
export type Message_Deserialize = {
	id: MessageId,
	role: Role,
	parts: ContentPart_Deserialize[],
	/**  The provider that produced an assistant message; `None` for user and system messages. */
	origin: ProviderKind | null,
	/**  Milliseconds since the Unix epoch. */
	created_at: number,
};

/**  One message in a transcript. */
export type Message_Serialize = {
	id: MessageId,
	role: Role,
	parts: ContentPart_Serialize[],
	/**  The provider that produced an assistant message; `None` for user and system messages. */
	origin: ProviderKind | null,
	/**  Milliseconds since the Unix epoch. */
	created_at: number,
};

/**  The permission mode of a chat (docs/plan/04 §3). */
export type Mode = "manual" | "auto_edit" | "plan" | "auto";

export type ModelCapabilities = {
	tools: boolean,
	parallel_tools: boolean,
	streams_tool_args: boolean,
	vision: boolean,
	pdf_input: boolean,
	reasoning: ReasoningSupport,
	server_web_search: boolean,
	structured_output: boolean,
	prompt_caching: CacheSupport,
};

/**  One row of a provider's model list, as the UI and the catalog cache see it. */
export type ModelInfo = {
	id: string,
	display_name: string,
	context_window: number | null,
	max_output: number | null,
	pricing: Pricing | null,
	capabilities: ModelCapabilities,
};

/**  A model on a provider. */
export type ModelRef = {
	provider: ProviderId,
	model: string,
};

export type PermissionDecision = { kind: "allow_once" } | 
/**  Allow, and remember the answer for the rest of this chat at the given scope (04 §8). */
{ kind: "allow_chat"; scope: GrantScope } | { kind: "deny" };

/**  What a permission card shows (04 §7). */
export type PermissionRequest = {
	call_id: CallId,
	connector: string,
	connector_name: string,
	tool: string,
	model_tool_name: string,
	tier: RiskTier,
	args: unknown,
	display: ToolDisplay,
	/**  The assistant's last sentence before the call, as "why". */
	why: string | null,
	/**  The tool's description, shown on hover. */
	description: string,
	/**  The standing scopes this call may be granted, beyond "allow once" (04 §7, §8). */
	scopes: GrantScope[],
};

/**  US dollars per million tokens. */
export type Pricing = {
	input_per_mtok: number | null,
	output_per_mtok: number | null,
	cache_read_per_mtok: number | null,
};

/**  A named group of chats with shared instructions, knowledge and defaults. */
export type ProjectId = string;

/**  The class of a provider failure (docs/plan/02 §7), shared by the client layer and the UI. */
export type ProviderErrorKind = 
/**  The key is missing, invalid or disabled. */
"auth" | 
/**  The account has no credit left. */
"insufficient_credits" | "rate_limited" | "overloaded" | "invalid_request" | "context_too_long" | 
/**  The model id is unknown to the provider. */
"not_found" | "network" | 
/**  The stream ended before the message did. */
"stream_interrupted" | 
/**  The model declined to answer. */
"refused" | "unknown";

/**  A provider account id: `anthropic`, `openai`, `google`, `xai`, `openrouter` or `custom:<ulid>`. */
export type ProviderId = string;

/**  Which client implementation produced or must replay a part. */
export type ProviderKind = "anthropic" | "open_ai_responses" | "open_ai_chat" | "gemini";

export type ProviderRow = {
	id: ProviderId,
	/**  The client implementation: `openai_chat`, `anthropic`, `openai_responses`, `gemini`. */
	kind: string,
	label: string,
	base_url: string | null,
	enabled: boolean,
	key: KeyStatus,
	default_model: string | null,
	/**  Whether this build has a client for the provider's kind. */
	available: boolean,
	/**
	 *  A user-added OpenAI-compatible endpoint (`custom:<ulid>`); the only kind that can be
	 *  removed.
	 */
	custom: boolean,
};

export type ProviderTest = {
	ok: boolean,
	info: KeyInfo | null,
	error: ErrorDto | null,
};

export type ProviderUpdate = {
	default_model: string | null,
	base_url: string | null,
};

export type ProvidersChanged = null;

/**  How much the model should think before answering. */
export type ReasoningEffort = "off" | "low" | "medium" | "high" | "max";

export type ReasoningSupport = { kind: "none" } | 
/**  Accepts an effort level. */
{ kind: "effort" } | 
/**  Accepts a token budget. */
{ kind: "budget" };

export type RenderError = {
	/**  `compile` or `runtime`. */
	phase: string,
	message: string,
	line: number | null,
	column: number | null,
};

export type RenderReport = {
	status: RenderStatus,
	errors?: RenderError[],
};

/**  What the renderer reported for one version (13 §2). */
export type RenderStatus = "ok" | "error" | 
/**  The renderer had not reported within the cap. */
"pending";

/**  One piece of a tool result. */
export type ResultPart = { kind: "text"; text: string } | { kind: "json"; json: unknown } | 
/**  Base64-encoded image bytes. */
{ kind: "image"; data: string; mime: string } | 
/**  A large in-memory object parked by a native connector (01 §7). */
{ kind: "resource"; handle: string; summary: string };

/**  What a tool can do to the world (docs/plan/04 §2). */
export type RiskTier = 
/**  Observes; no side effects. */
"read" | 
/**  Mutates local state inside the chat's roots in a way Gantry can revert. */
"write" | 
/**  Mutates state outside the machine or the roots; not revertible by Gantry. */
"write_external" | 
/**  Runs code with unknown blast radius. */
"execute" | 
/**  Irreversible deletion or force operations. */
"destructive" | 
/**  Acts only on Gantry's own state; never prompts, always logged. */
"app";

/**  Who wrote a message. */
export type Role = "user" | "assistant" | "tool" | "system";

/**  A runtime an entry needs before it can be installed (03 §11 step 1). */
export type RuntimeRequirement = {
	/**  `node`, `python`, `uv` or `docker`. */
	name: string,
	/**  The version range asked for, as written in the manifest. */
	version: string,
};

/**  One row of the palette's search (docs/plan/06 §3): a chat by title or a message by text. */
export type SearchHit = {
	kind: SearchHitKind,
	chat_id: ChatId,
	chat_title: string,
	message_id: MessageId | null,
	turn_id: TurnId | null,
	/**  The matched title, or the matching stretch of the message with `…` around it. */
	snippet: string,
	ts: number,
};

export type SearchHitKind = "chat" | "message";

/**  Where the master key lives; shown in Settings → Providers. */
export type SecretStoreStatus = 
/**  The operating system's credential store. */
{ kind: "os_store"; backend: string } | 
/**  A file in the data directory, readable by the user only. Linux without Secret Service. */
{ kind: "file_fallback"; path: string };

/**  What the server said about itself on the last connection (06 §3, `server_info_json`). */
export type ServerInfo = {
	name: string,
	version: string,
	/**  The negotiated MCP revision, shown on the detail page (03 §6). */
	protocol: string,
};

/**  Every setting, with a default in code. Persisted one section per row (11 §1). */
export type Settings = {
	appearance?: AppearanceSettings,
	chat?: ChatSettings,
	advanced?: AdvancedSettings,
};

export type SettingsChanged = null;

/**  A section-level patch: every present section replaces the stored one. */
export type SettingsPatch = {
	appearance?: AppearanceSettings | null,
	chat?: ChatSettings | null,
	advanced?: AdvancedSettings | null,
};

/**  Why the model stopped. */
export type StopReason = { kind: "end_turn" } | { kind: "tool_use" } | { kind: "max_tokens" } | { kind: "refusal"; category: string | null } | { kind: "content_filter" } | { kind: "pause_turn" } | { kind: "cancelled" } | { kind: "other"; reason: string };

/**  What developer mode shows: the frozen prompt and the notes appended since (10 §4). */
export type SystemPromptView = {
	snapshot: string,
	notes: string[],
};

export type Theme = "system" | "light" | "dark";

/**
 *  A tool call as the activity feed and the detail pane see it: the `tool_calls` row plus the
 *  result kept in the transcript.
 */
export type ToolCallDto = {
	id: CallId,
	chat_id: ChatId,
	turn_id: TurnId,
	/**  The assistant message that requested the call. */
	message_id: MessageId,
	/**  The namespace prefix the model used: a connector id, or `gantry` for runtime tools. */
	connector: string,
	connector_name: string,
	/**  Un-namespaced tool name. */
	tool: string,
	/**  The name the model used, e.g. `gantry__clock`. */
	model_tool_name: string,
	args: unknown,
	tier: RiskTier,
	status: ToolCallStatus,
	decision_source: DecisionSource | null,
	display: ToolDisplay,
	/**  The first part of the result as text, for the row and the projection. */
	result_preview: string | null,
	/**
	 *  The full result when it is known: from the transcript for a finished turn, from the
	 *  completion event while the turn runs.
	 */
	result: ResultPart[] | null,
	is_error: boolean,
	started_at: number | null,
	ended_at: number | null,
	duration_ms: number | null,
};

/**  Where a tool call is in its life (06 §3, `tool_calls.status`). */
export type ToolCallStatus = 
/**  The model asked for it; arguments may still be streaming. */
"proposed" | "awaiting_decision" | "denied" | "running" | "completed" | "failed" | "cancelled";

export type ToolDisplay = {
	kind: ToolDisplayKind,
	/**  A one-line argument summary in the row, e.g. `path=src/app.rs` or `$ npm test`. */
	summary: string,
};

/**  How the activity row renders a call (05 §2, `tool_call.ready.display`). */
export type ToolDisplayKind = "edit" | "command" | "connector" | "read";

/**
 *  One tool an instance offers, as the UI lists it. The schema is not carried here: the browse
 *  list wants names and tiers, and the model gets the schema from the live session.
 */
export type ToolInfo = {
	name: string,
	title: string | null,
	description: string,
	tier: RiskTier,
};

/**  One user message and everything the assistant did in reply. */
export type TurnDto = TurnDto_Serialize | TurnDto_Deserialize;

/**  One user message and everything the assistant did in reply. */
export type TurnDto_Deserialize = {
	id: TurnId,
	status: TurnStatus,
	model: ModelRef,
	user: Message_Deserialize,
	/**
	 *  The assistant and tool messages of the turn in order: one assistant message per model
	 *  round, a tool message after each round that called tools. Empty while the turn runs;
	 *  the live messages come through the channel.
	 */
	messages: Message_Deserialize[],
	/**  Every tool call of the turn, in the order the model made them. */
	tool_calls: ToolCallDto[],
	/**  Provider and loop notices shown inline (05 §1): a round cap, a dropped block, a retry. */
	notices: string[],
	usage: Usage | null,
	stop_reason: StopReason | null,
	error: string | null,
	feedback: Feedback | null,
	started_at: number,
	ended_at: number | null,
};

/**  One user message and everything the assistant did in reply. */
export type TurnDto_Serialize = {
	id: TurnId,
	status: TurnStatus,
	model: ModelRef,
	user: Message_Serialize,
	/**
	 *  The assistant and tool messages of the turn in order: one assistant message per model
	 *  round, a tool message after each round that called tools. Empty while the turn runs;
	 *  the live messages come through the channel.
	 */
	messages: Message_Serialize[],
	/**  Every tool call of the turn, in the order the model made them. */
	tool_calls: ToolCallDto[],
	/**  Provider and loop notices shown inline (05 §1): a round cap, a dropped block, a retry. */
	notices: string[],
	usage: Usage | null,
	stop_reason: StopReason | null,
	error: string | null,
	feedback: Feedback | null,
	started_at: number,
	ended_at: number | null,
};

/**  One unit of agent work: a user message and everything until the assistant stops. */
export type TurnId = string;

/**
 *  What a late subscriber needs to draw an in-flight turn: every message of the turn so far
 *  (the last one may still be streaming), the tool calls and the pending decisions.
 */
export type TurnSnapshot = TurnSnapshot_Serialize | TurnSnapshot_Deserialize;

/**
 *  What a late subscriber needs to draw an in-flight turn: every message of the turn so far
 *  (the last one may still be streaming), the tool calls and the pending decisions.
 */
export type TurnSnapshot_Deserialize = {
	chat_id: ChatId,
	status: TurnStatus,
	/**  Assistant and tool messages of the turn in order; parts in block order. */
	messages: Message_Deserialize[],
	tool_calls: ToolCallDto[],
	pending: Interaction[],
	usage: Usage | null,
	started_at: number,
	/**  The last `seq` this snapshot covers; live events continue from `seq + 1`. */
	seq: number,
};

/**
 *  What a late subscriber needs to draw an in-flight turn: every message of the turn so far
 *  (the last one may still be streaming), the tool calls and the pending decisions.
 */
export type TurnSnapshot_Serialize = {
	chat_id: ChatId,
	status: TurnStatus,
	/**  Assistant and tool messages of the turn in order; parts in block order. */
	messages: Message_Serialize[],
	tool_calls: ToolCallDto[],
	pending: Interaction[],
	usage: Usage | null,
	started_at: number,
	/**  The last `seq` this snapshot covers; live events continue from `seq + 1`. */
	seq: number,
};

export type TurnStatus = "running" | "completed" | "cancelled" | "failed" | 
/**  The app was closed while the turn ran (found at the next start). */
"interrupted";

/**  Token accounting for one request, in the provider's own count. */
export type Usage = {
	input: number,
	output: number,
	cache_read: number,
	cache_write: number,
	reasoning: number,
	/**  What the provider says the request cost, in US dollars, when it says so (OpenRouter does). */
	cost_usd: number | null,
};

/**  Who made a version (13 §7). */
export type VersionSource = "model_create" | "model_update" | "model_edit" | "user_edit" | "user_restore";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

